'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const src = fs.readFileSync(path.join(root, 'docs/scifi-ui/scripts/formatx-reference-core-v26.js'), 'utf8');
const css = fs.readFileSync(path.join(root, 'docs/scifi-ui/styles/formatx-reference-core-v26.css'), 'utf8');
const entry = fs.readFileSync(path.join(root, 'billing-worker/src/production-entry.js'), 'utf8');

assert.match(src, /const VERSION = 'v26'/, 'v26 renderer marker missing');
assert.match(src, /canvas\.getContext\('webgl2'/, 'native WebGL2 context missing');
assert.equal((src.match(/getContext\('webgl2'/g) || []).length >= 1, true, 'WebGL2 acquisition missing');
assert.match(src, /gl\.DEPTH_TEST/, 'depth testing missing');
assert.match(src, /gl\.DEPTH_COMPONENT16/, 'depth attachment missing');
assert.match(src, /function perspective\(/, 'perspective projection missing');
assert.match(src, /function lookAt\(/, '3D camera view matrix missing');
assert.match(src, /function crystalGeometry\(/, 'indexed crystal geometry missing');
assert.match(src, /function sphereGeometry\(/, 'reactor sphere geometry missing');
assert.match(src, /function torusGeometry\(/, '3D reactor ring geometry missing');
assert.match(src, /function planeGeometry\(/, '3D floor plane missing');
assert.match(src, /gl\.drawElements\(gl\.TRIANGLES/, 'indexed triangle rendering missing');
assert.match(src, /gl\.drawElements\(gl\.LINES/, 'integrated crystal line rendering missing');
assert.match(src, /rotationX\([^\n]+time/, 'time-driven X-axis 3D animation missing');
assert.match(src, /rotationY\([^\n]+time/, 'time-driven Y-axis 3D animation missing');
assert.match(src, /rotationZ\([^\n]+time/, 'time-driven Z-axis 3D animation missing');
assert.match(src, /independent-shell-reactor-orbits/, 'independent reactor animation marker missing');
assert.match(src, /true-indexed-four-tip-concave-crystal/, 'reference four-tip geometry marker missing');
assert.match(src, /native-webgl2-reference-crystal-v26/, 'renderer identity marker missing');
assert.match(src, /uScene/, 'post-process scene texture missing');
assert.match(src, /uBloom/, 'post-process bloom missing');
assert.match(src, /WEBGL_lose_context/, 'legacy renderer retirement/recovery control missing');
assert.match(src, /requestAnimationFrame\(render\)/, 'display-synchronised animation loop missing');
assert.match(src, /renderScale/, 'adaptive render scale missing');
assert.match(src, /ema > 19\.8/, 'adaptive slow-frame threshold missing');
assert.doesNotMatch(src, /new\s+Image\s*\(|drawImage\s*\(|createImageBitmap\s*\(/i, 'reference core must not be image-backed');
assert.doesNotMatch(src, /THREE\b|three\.js|babylon|playcanvas|model-viewer/i, 'third-party scene engine is forbidden for v26 core');
assert.doesNotMatch(src, /backgroundImage|background-image/i, 'renderer must not fake the core with a background image');
assert.match(css, /pointer-events:\s*none/, '3D stage must never capture scrolling or touch input');
assert.match(css, /100dvh/, 'dynamic mobile viewport support missing');
assert.match(css, /data-fx-reference-core="ready-v26"/, 'v26 presentation state missing');
assert.match(entry, /formatx-reference-core-v26\.js\?v=20260809-reference-crystal-v26-1/, 'production v26 script injection missing');
assert.match(entry, /formatx-reference-core-v26\.css\?v=20260809-reference-crystal-v26-1/, 'production v26 CSS injection missing');
assert.match(entry, /CRITICAL_STARTUP_ASSETS[\s\S]*formatx-reference-core-v26\.js/, 'v26 asset no-store protection missing');
console.log('PASS: FormatX reference core v26 is a native indexed WebGL2 crystal with depth, perspective, independent 3D reactor motion, procedural glass shading, bloom and adaptive rendering; no image-backed or third-party 3D shortcut detected.');
